    {
        Debug.Log($"[FeedbackManager] Swing VFX \u2014 tool {evt.ToolType}, aim point {evt.AimPoint}");
    }

    private void OnToolHitTarget(ToolHitTarget evt)
    {
        Debug.Log($"[FeedbackManager] Impact VFX at {evt.Hit.HitPoint} \u2014 tool {evt.Hit.ToolType}, damage {evt.Hit.Damage}");
    }

    private void OnItemPickedUp(ItemPickedUp evt)
    {
