    }

    private void OnRopeGrappleStarted(RopeGrappleStarted evt)
    {
        Debug.Log($"[FeedbackManager] Grapple launch effect \u2014 anchor {evt.Anchor?.name ?? "unknown"}");
    }

    private void OnBatteryLow(BatteryLow evt)
    {
        Debug.Log($"[FeedbackManager] Warning pulse \u2014 battery {evt.Current} ({evt.Percent:P0})");
    }

    private void OnBatteryEmpty(BatteryEmpty evt)
    {
        Debug.Log("[FeedbackManager] Screen flash \u2014 battery empty");
    }
}

